  var LANG_KEY = "artbent_lang";
  var LANGS = { ru: 1, en: 1, hy: 1 };
  function norm(s) { return s.replace(/\u00A0/g, " ").replace(/\s+/g, " ").trim(); }

  var MAP = {};
  Object.keys(DICT).forEach(function (ru) {
    MAP[norm(ru)] = { ru: ru, en: DICT[ru][0], hy: DICT[ru][1] };
  });

  function getLang() {
    try { var l = localStorage.getItem(LANG_KEY); return LANGS[l] ? l : "ru"; } catch (e) { return "ru"; }
  }
  var lang = getLang();
  var observer = null;
  var muting = false;
  var scheduled = false;

  function translate(node) {
    if (node.nodeType === 3) {
      var raw = node.nodeValue;
      if (!raw || !raw.trim()) return;
      var entry = node.__i18n;
      if (!entry) { entry = MAP[norm(raw)]; if (entry) node.__i18n = entry; }
      if (entry) {
        var target = entry[lang] || entry.ru;
        if (node.nodeValue !== target) node.nodeValue = target;
      }
      return;
    }
    if (node.nodeType === 1) {
      var tag = node.tagName;
      if (tag === "SCRIPT" || tag === "STYLE" || node.hasAttribute("data-lang")) {
        if (node.hasAttribute("data-lang")) return; // never translate the switch labels
        return;
      }
      ["placeholder", "title", "aria-label"].forEach(function (attr) {
        if (!node.hasAttribute(attr)) return;
        var attrValue = node.getAttribute(attr);
        var attrEntry = node.__i18nAttrs && node.__i18nAttrs[attr];
        if (!attrEntry) {
          attrEntry = MAP[norm(attrValue)];
          if (attrEntry) {
            if (!node.__i18nAttrs) node.__i18nAttrs = {};
            node.__i18nAttrs[attr] = attrEntry;
          }
        }
        if (attrEntry) node.setAttribute(attr, attrEntry[lang] || attrEntry.ru);
      });
      if (tag === "INPUT" || tag === "TEXTAREA") {
        var fieldEntry = node.__i18nValue || MAP[norm(node.value || "")];
        if (fieldEntry) node.__i18nValue = fieldEntry;
        if (fieldEntry) node.value = fieldEntry[lang] || fieldEntry.ru;
      }
      var kids = node.childNodes;
      for (var i = 0; i < kids.length; i++) translate(kids[i]);
    }
  }

  function startObserve() {
    if (!document.body || typeof MutationObserver === "undefined") return;
    observer = new MutationObserver(function () {
      if (muting) return;
      muting = true;
      refresh();
      muting = false;
    });
    observer.observe(document.body, { childList: true, subtree: true, characterData: true });
  }

  function apply() {
    if (document.body) translate(document.body);
  }

  function paintSwitch() {
    var els = document.querySelectorAll("[data-lang]");
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      var l = el.getAttribute("data-lang");
      if (!el.__bound) {
        el.__bound = true;
        el.style.cursor = "pointer";
        (function (lg) { el.addEventListener("click", function (e) { e.preventDefault(); setLang(lg); }); })(l);
      }
      var on = l === lang;
      var dark = el.getAttribute("data-lang-theme") === "dark";
      el.style.fontWeight = on ? "700" : "500";
      if (dark) {
        el.style.background = on ? "#EFE8DB" : "transparent";
        el.style.color = on ? "#2A231C" : "#9A8F7E";
      } else {
        el.style.background = on ? "#2A231C" : "transparent";
        el.style.color = on ? "#EFE8DB" : "#786C5C";
      }
    }
  }

  function refresh() { apply(); paintSwitch(); }

  function setLang(l) {
    if (!LANGS[l]) return;
    lang = l;
    try { localStorage.setItem(LANG_KEY, l); } catch (e) {}
    document.documentElement.setAttribute("lang", l === "hy" ? "hy" : l);
    refresh();
  }

  var clickTimer = null;
  function onClick() {
    // a click may trigger a React re-render (FAQ toggle, filter, etc.) — re-translate shortly after
    if (clickTimer) clearTimeout(clickTimer);
    clickTimer = setTimeout(refresh, 60);
  }

  function init() {
    refresh();
    startObserve();
    // catch content the DC runtime mounts asynchronously after first paint
    [120, 350, 800, 1500].forEach(function (t) { setTimeout(refresh, t); });
    document.addEventListener("click", onClick, true);
    window.addEventListener("hashchange", function () { setTimeout(refresh, 60); });
    document.documentElement.setAttribute("lang", lang === "hy" ? "hy" : lang);
  }

